def shlex_split(s):
    tokens = []
    current = []
    i = 0
    n = len(s)

    while i < n:
        c = s[i]

        # Skip whitespace
        if c in ' \t\n\r':
            if current:
                tokens.append(''.join(current))
                current = []
            i += 1
            continue

        # Single quote: everything literal inside, no escapes
        if c == "'":
            i += 1
            while i < n and s[i] != "'":
                current.append(s[i])
                i += 1
            if i < n:
                i += 1  # skip closing quote
            # If we reached end of string without closing quote, that's an error
            # but we'll just stop here
            continue

        # Double quote: backslash escapes only another backslash or double quote
        if c == '"':
            i += 1
            while i < n and s[i] != '"':
                if s[i] == '\\':
                    if i + 1 < n and s[i + 1] in ('\\', '"'):
                        current.append(s[i + 1])
                        i += 2
                    else:
                        current.append('\\')
                        i += 1
                else:
                    current.append(s[i])
                    i += 1
            if i < n:
                i += 1  # skip closing quote
            continue

        # Backslash outside quotes: escapes the next character
        if c == '\\':
            if i + 1 < n:
                current.append(s[i + 1])
                i += 2
            else:
                # Trailing backslash: keep it literal? shlex raises error, but let's just append it
                current.append('\\')
                i += 1
            continue

        # Regular character
        current.append(c)
        i += 1

    if current:
        tokens.append(''.join(current))

    return tokens
